class RequireResourceTagsPolicy(Construct):
    """Require mandatory tags on S3 buckets, EC2 instances, and RDS clusters.

    This policy denies creation of S3 buckets, EC2 instances, or RDS clusters
    unless the resource is tagged with 'CostCenter', 'DataClassification', and 'Owner'.

    Compliance and Governance Benefits:
        - Ensures all resources have proper cost allocation tags
        - Enforces data classification for security and compliance
        - Maintains accountability through ownership tracking
        - Enables accurate cost reporting and chargeback
    """

    def __init__(
        self,
        scope: Construct,
        organization: CfnOrganization,
        **kwargs,
    ):
        super().__init__(scope, "RequireResourceTagsPolicy", **kwargs)

        # Create the policy document that requires tags on resource creation
        policy_document = {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "DenyS3BucketCreationWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": "s3:CreateBucket",
                    "Resource": "*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/CostCenter": "true"
                        }
                    }
                },
                {
                    "Sid": "DenyS3BucketCreationWithoutDataClassification",
                    "Effect": "Deny",
                    "Action": "s3:CreateBucket",
                    "Resource": "*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/DataClassification": "true"
                        }
                    }
                },
                {
                    "Sid": "DenyS3BucketCreationWithoutOwner",
                    "Effect": "Deny",
                    "Action": "s3:CreateBucket",
                    "Resource": "*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/Owner": "true"
                        }
                    }
                },
                {
                    "Sid": "DenyEC2InstanceCreationWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": "ec2:RunInstances",
                    "Resource": "arn:aws:ec2:*:*:instance/*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/CostCenter": "true"
                        }
                    }
                },
                {
                    "Sid": "DenyEC2InstanceCreationWithoutDataClassification",
                    "Effect": "Deny",
                    "Action": "ec2:RunInstances",
                    "Resource": "arn:aws:ec2:*:*:instance/*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/DataClassification": "true"
                        }
                    }
                },
                {
                    "Sid": "DenyEC2InstanceCreationWithoutOwner",
                    "Effect": "Deny",
                    "Action": "ec2:RunInstances",
                    "Resource": "arn:aws:ec2:*:*:instance/*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/Owner": "true"
                        }
                    }
                },
                {
                    "Sid": "DenyRDSClusterCreationWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": "rds:CreateDBCluster",
                    "Resource": "*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/CostCenter": "true"
                        }
                    }
                },
                {
                    "Sid": "DenyRDSClusterCreationWithoutDataClassification",
                    "Effect": "Deny",
                    "Action": "rds:CreateDBCluster",
                    "Resource": "*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/DataClassification": "true"
                        }
                    }
                },
                {
                    "Sid": "DenyRDSClusterCreationWithoutOwner",
                    "Effect": "Deny",
                    "Action": "rds:CreateDBCluster",
                    "Resource": "*",
                    "Condition": {
                        "Null": {
                            "aws:RequestTag/Owner": "true"
                        }
                    }
                }
            ],
        }

        # Create the SCP in AWS Organizations
        scp = CfnPolicy(
            self,
            "RequireResourceTagsPolicy",
            content=policy_document,
            description="Require CostCenter, DataClassification, and Owner tags on S3 buckets, EC2 instances, and RDS clusters.",
            name="RequireResourceTags",
            type="SERVICE_CONTROL_POLICY",
        )

        scp.target_ids = [organization.attr_root_id]

        # Tag the policy for easier identification and management
        Tags.of(scp).add("Purpose", "Governance")
        Tags.of(scp).add("ComplianceControl", "ResourceTagging")

