from aws_cdk import Tags
from aws_cdk.aws_organizations import CfnOrganization, CfnPolicy
from constructs import Construct


class RequireResourceTagsPolicy(Construct):
    """Require mandatory tags on S3 buckets, EC2 instances, and RDS clusters.

    This policy ensures that all S3 buckets, EC2 instances, and RDS clusters are tagged
    with 'CostCenter', 'DataClassification', and 'Owner' at creation time to enable
    proper cost allocation, data governance, and accountability.
    """

    def __init__(
        self,
        scope: Construct,
        organization: CfnOrganization,
        **kwargs,
    ):
        super().__init__(scope, "RequireResourceTagsPolicy", **kwargs)

        # Define the required tags
        required_tags = ["CostCenter", "DataClassification", "Owner"]

        # Create the policy document that requires tags on resource creation
        policy_document = {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "DenyS3BucketCreationWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": [
                        "s3:CreateBucket",
                        "s3:PutBucketTagging"
                    ],
                    "Resource": "*",
                    "Condition": {
                        "ForAnyValue:StringNotEquals": {
                            "aws:TagKeys": required_tags
                        }
                    }
                },
                {
                    "Sid": "DenyEC2InstanceCreationWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": "ec2:RunInstances",
                    "Resource": "arn:aws:ec2:*:*:instance/*",
                    "Condition": {
                        "ForAnyValue:StringNotEquals": {
                            "aws:RequestTag/CostCenter": ["*"],
                            "aws:RequestTag/DataClassification": ["*"],
                            "aws:RequestTag/Owner": ["*"]
                        }
                    }
                },
                {
                    "Sid": "DenyRDSClusterCreationWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": [
                        "rds:CreateDBCluster",
                        "rds:CreateDBInstance"
                    ],
                    "Resource": [
                        "arn:aws:rds:*:*:cluster:*",
                        "arn:aws:rds:*:*:db:*"
                    ],
                    "Condition": {
                        "ForAnyValue:StringNotEquals": {
                            "aws:RequestTag/CostCenter": ["*"],
                            "aws:RequestTag/DataClassification": ["*"],
                            "aws:RequestTag/Owner": ["*"]
                        }
                    }
                }
            ],
        }

        # Create the SCP in AWS Organizations
        scp = CfnPolicy(
            self,
            "RequireResourceTagsPolicy",
            content=policy_document,
            description="Requires CostCenter, DataClassification, and Owner tags on S3 buckets, EC2 instances, and RDS clusters",
            name="Require-Resource-Tags",
            type="SERVICE_CONTROL_POLICY",
        )

        scp.target_ids = [organization.attr_root_id]

        # Tag the policy for easier identification and management
        Tags.of(scp).add("Purpose", "Governance")
        Tags.of(scp).add("SecurityControl", "ResourceTagging")

